package main

import (
	"bytes"
	"errors"
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"

	"go.yaml.in/yaml/v3"
)

// File is one generated file, with a path relative to skills/.
type File struct {
	Path string
	Data []byte
}

const header = "<!-- Code generated by skills/internal/gen from api/bundled/openapi.yaml. DO NOT EDIT. -->\n\n"

// Generate builds the generated references from the bundled contract.
func Generate(spec []byte) ([]File, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(spec, &root); err != nil {
		return nil, fmt.Errorf("parse contract: %w", err)
	}
	if len(root.Content) != 1 || root.Content[0].Kind != yaml.MappingNode {
		return nil, errors.New("contract is not a YAML mapping")
	}
	d := &doc{root: root.Content[0]}
	manifest, err := d.manifestFields()
	if err != nil {
		return nil, err
	}
	tools, err := d.tools()
	if err != nil {
		return nil, err
	}
	codes, err := d.errorCodes()
	if err != nil {
		return nil, err
	}
	return []File{
		{Path: "lerryn-automation/references/manifest-fields.md", Data: manifest},
		{Path: "lerryn-automation/references/tools.md", Data: tools},
		{Path: "lerryn-troubleshoot/references/error-codes.md", Data: codes},
	}, nil
}

type doc struct{ root *yaml.Node }

// get returns the value of key in a mapping node, or nil.
func get(n *yaml.Node, key string) *yaml.Node {
	if n == nil || n.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}

// pairs returns the key and value nodes of a mapping in document order.
func pairs(n *yaml.Node) [][2]*yaml.Node {
	if n == nil || n.Kind != yaml.MappingNode {
		return nil
	}
	out := make([][2]*yaml.Node, 0, len(n.Content)/2)
	for i := 0; i+1 < len(n.Content); i += 2 {
		out = append(out, [2]*yaml.Node{n.Content[i], n.Content[i+1]})
	}
	return out
}

func scalar(n *yaml.Node) string {
	if n == nil || n.Kind != yaml.ScalarNode {
		return ""
	}
	return n.Value
}

// resolve follows local $ref pointers.
func (d *doc) resolve(n *yaml.Node) (*yaml.Node, error) {
	for range 32 {
		ref := scalar(get(n, "$ref"))
		if ref == "" {
			return n, nil
		}
		ptr, ok := strings.CutPrefix(ref, "#/")
		if !ok {
			return nil, fmt.Errorf("unsupported $ref %q", ref)
		}
		cur := d.root
		for _, part := range strings.Split(ptr, "/") {
			part = strings.ReplaceAll(strings.ReplaceAll(part, "~1", "/"), "~0", "~")
			cur = get(cur, part)
			if cur == nil {
				return nil, fmt.Errorf("unresolved $ref %q", ref)
			}
		}
		n = cur
	}
	return nil, errors.New("$ref chain too long")
}

func (d *doc) schema(name string) (*yaml.Node, error) {
	s := get(get(get(d.root, "components"), "schemas"), name)
	if s == nil {
		return nil, fmt.Errorf("schema %s not in the contract", name)
	}
	return s, nil
}

// nonNull returns the non-null branch of a `oneOf: [X, {type: null}]`.
func (d *doc) nonNull(n *yaml.Node) (*yaml.Node, error) {
	one := get(n, "oneOf")
	if one == nil || one.Kind != yaml.SequenceNode {
		return n, nil
	}
	var keep []*yaml.Node
	for _, b := range one.Content {
		if scalar(get(b, "type")) != "null" {
			keep = append(keep, b)
		}
	}
	if len(keep) != 1 {
		return n, nil
	}
	return d.resolve(keep[0])
}

// cell makes text safe for one Markdown table cell. Line breaks inside
// Chinese text are dropped rather than turned into spaces: the contract
// wraps long Chinese lines, and a space would land inside a sentence.
func cell(s string) string {
	var b strings.Builder
	lines := strings.Split(strings.TrimSpace(s), "\n")
	for i, l := range lines {
		l = strings.TrimSpace(l)
		if i > 0 && l != "" && b.Len() > 0 {
			prev, _ := utf8.DecodeLastRuneInString(b.String())
			next, _ := utf8.DecodeRuneInString(l)
			if !isCJK(prev) && !isCJK(next) {
				b.WriteByte(' ')
			}
		}
		b.WriteString(l)
	}
	return strings.ReplaceAll(b.String(), "|", `\|`)
}

func isCJK(r rune) bool {
	return unicode.Is(unicode.Han, r) || (r >= 0x3000 && r <= 0x303f) || (r >= 0xff00 && r <= 0xffef)
}

// typeName describes a resolved schema: string, integer, array of string…
func (d *doc) typeName(s *yaml.Node) (string, error) {
	t := get(s, "type")
	var types []string
	switch {
	case t == nil:
	case t.Kind == yaml.SequenceNode:
		for _, x := range t.Content {
			if x.Value != "null" {
				types = append(types, x.Value)
			}
		}
	default:
		types = []string{t.Value}
	}
	if len(types) == 1 && types[0] == "array" {
		items, err := d.resolve(get(s, "items"))
		if err != nil {
			return "", err
		}
		inner, err := d.typeName(items)
		if err != nil {
			return "", err
		}
		return "array of " + inner, nil
	}
	if len(types) == 0 {
		return "any", nil
	}
	return strings.Join(types, " or "), nil
}

// rules lists a schema's constraints in a compact form.
func rules(s *yaml.Node) string {
	var out []string
	if e := get(s, "enum"); e != nil {
		vals := make([]string, 0, len(e.Content))
		for _, v := range e.Content {
			vals = append(vals, "`"+v.Value+"`")
		}
		out = append(out, "取值 "+strings.Join(vals, "、"))
	}
	if p := scalar(get(s, "pattern")); p != "" {
		out = append(out, "格式 `"+p+"`")
	}
	for _, k := range [][2]string{
		{"minimum", "最小"}, {"maximum", "最大"}, {"minLength", "最短"}, {"maxLength", "最长"},
		{"minItems", "至少"}, {"maxItems", "最多"},
	} {
		if v := scalar(get(s, k[0])); v != "" {
			unit := ""
			switch k[0] {
			case "minLength", "maxLength":
				unit = " 个字符"
			case "minItems", "maxItems":
				unit = " 项"
			}
			out = append(out, k[1]+" "+v+unit)
		}
	}
	if get(s, "uniqueItems") != nil && scalar(get(s, "uniqueItems")) == "true" {
		out = append(out, "不重复")
	}
	return strings.Join(out, "；")
}

func defaultOf(s *yaml.Node) string {
	v := get(s, "default")
	if v == nil {
		return ""
	}
	if v.Kind == yaml.ScalarNode {
		return "`" + v.Value + "`"
	}
	var b bytes.Buffer
	enc := yaml.NewEncoder(&b)
	enc.SetIndent(2)
	_ = enc.Encode(v)
	return "`" + strings.TrimSpace(b.String()) + "`"
}

type fieldRow struct {
	path, typ, required, def, rules, desc string
}

func (d *doc) manifestFields() ([]byte, error) {
	m, err := d.schema("Manifest")
	if err != nil {
		return nil, err
	}
	var rows []fieldRow
	if err := d.walkFields("", m, &rows, 0); err != nil {
		return nil, err
	}
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# 清单字段\n\n")
	b.WriteString("任务清单（`task_apply` 的 `manifest`）的全部字段，由接口契约中的 `Manifest` schema 生成。用法和示例见 [manifest.md](manifest.md)。")
	b.WriteString("清单不接受未列出的字段。`[]` 表示数组中的每一项。\n\n")
	b.WriteString("| 字段 | 类型 | 必填 | 默认值 | 约束 | 说明 |\n| --- | --- | --- | --- | --- | --- |\n")
	for _, r := range rows {
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %s | %s |\n", r.path, r.typ, r.required, r.def, cell(r.rules), cell(r.desc))
	}
	return []byte(b.String()), nil
}

func (d *doc) walkFields(prefix string, s *yaml.Node, rows *[]fieldRow, depth int) error {
	if depth > 8 {
		return errors.New("manifest schema nests too deep")
	}
	s, err := d.resolve(s)
	if err != nil {
		return err
	}
	required := map[string]bool{}
	if req := get(s, "required"); req != nil {
		for _, r := range req.Content {
			required[r.Value] = true
		}
	}
	for _, kv := range pairs(get(s, "properties")) {
		name, raw := kv[0].Value, kv[1]
		ps, err := d.resolve(raw)
		if err != nil {
			return err
		}
		if ps, err = d.nonNull(ps); err != nil {
			return err
		}
		desc := scalar(get(raw, "description"))
		if desc == "" {
			desc = scalar(get(ps, "description"))
		}
		typ, err := d.typeName(ps)
		if err != nil {
			return err
		}
		path := prefix + name
		req := ""
		if required[name] {
			req = "是"
		}
		ruleSrc := ps
		if scalar(get(ps, "type")) == "array" {
			items, err := d.resolve(get(ps, "items"))
			if err != nil {
				return err
			}
			r := rules(ps)
			if ir := rules(items); ir != "" && get(items, "properties") == nil {
				r = strings.Trim(r+"；每项"+ir, "；")
			}
			*rows = append(*rows, fieldRow{path, typ, req, defaultOf(ps), r, desc})
			if get(items, "properties") != nil {
				if err := d.walkFields(path+"[].", items, rows, depth+1); err != nil {
					return err
				}
			}
			continue
		}
		*rows = append(*rows, fieldRow{path, typ, req, defaultOf(ruleSrc), rules(ruleSrc), desc})
		if get(ps, "properties") != nil {
			if err := d.walkFields(path+".", ps, rows, depth+1); err != nil {
				return err
			}
		}
	}
	return nil
}

// friendlyCLI maps tools to the lerryn CLI's own commands (docs/zh-CN/cli.md).
var friendlyCLI = map[string]string{
	"discover":   "`lerryn discover`",
	"task_apply": "`lerryn tasks apply <目录>`",
	"task_get":   "`lerryn tasks get <任务>`",
	"run_start":  "`lerryn runs start <任务>`",
	"run_get":    "`lerryn runs get <运行>`、`lerryn runs wait <运行>`",
	"run_logs":   "`lerryn runs logs <运行>`",
	"run_cancel": "`lerryn runs cancel <运行>`",
}

var scopeOf = map[string]string{"read": "read", "mutate": "write", "execute": "execute"}

func (d *doc) tools() ([]byte, error) {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# MCP 工具与 CLI\n\n")
	b.WriteString("由接口契约中各操作的 `x-mcp` 生成。每个工具对应一个 API 操作；CLI 用 `lerryn api <operationId>` 调用同一个操作，参数名与工具相同（选项里下划线写作连字符）。")
	b.WriteString("访问令牌需要表中的范围。没有独立工具的操作用 `api_describe` 查说明，用 `api_call` 调用。\n\n")
	b.WriteString("| 工具 | 操作 | 类型 | 令牌范围 | CLI |\n| --- | --- | --- | --- | --- |\n")
	type tool struct{ name, title, desc string }
	var list []tool
	for _, pv := range pairs(get(d.root, "paths")) {
		item, err := d.resolve(pv[1])
		if err != nil {
			return nil, err
		}
		for _, mv := range pairs(item) {
			method := strings.ToUpper(mv[0].Value)
			switch method {
			case "GET", "PUT", "POST", "DELETE", "PATCH":
			default:
				continue
			}
			op := mv[1]
			x := get(op, "x-mcp")
			if scalar(get(x, "expose")) != "true" {
				continue
			}
			name := scalar(get(x, "tool"))
			opID := scalar(get(op, "operationId"))
			kind := scalar(get(op, "x-operation-kind"))
			cli := "`lerryn api " + opID + "`"
			if f, ok := friendlyCLI[name]; ok {
				cli = f + "，" + cli
			}
			fmt.Fprintf(&b, "| `%s` | `%s` `%s %s` | %s | `%s` | %s |\n", name, opID, method, pv[0].Value, kind, scopeOf[kind], cli)
			title := scalar(get(x, "title"))
			if title == "" {
				title = scalar(get(op, "summary"))
			}
			list = append(list, tool{name, title, scalar(get(x, "description"))})
		}
	}
	b.WriteString("| `api_describe` | 任意操作的说明和 schema | read | `read` | `lerryn api <operationId> --describe` |\n")
	b.WriteString("| `api_call` | 按 operationId 调用任意公开操作，参数放在 `arguments` 里：`{\"operation_id\": \"getCredentialRequest\", \"arguments\": {\"request_id\": \"<id>\"}}` | 视操作而定 | 视操作而定 | `lerryn api <operationId>` |\n")
	b.WriteString("\n## 工具说明\n")
	for _, t := range list {
		fmt.Fprintf(&b, "\n### %s（%s）\n\n%s\n", t.name, t.title, strings.TrimSpace(t.desc))
	}
	return []byte(b.String()), nil
}

func (d *doc) errorCodes() ([]byte, error) {
	ec, err := d.schema("ErrorCode")
	if err != nil {
		return nil, err
	}
	one := get(ec, "oneOf")
	if one == nil || len(one.Content) == 0 {
		return nil, errors.New("ErrorCode has no oneOf values")
	}
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# 错误码\n\n")
	b.WriteString("由接口契约中的 `ErrorCode` 生成。API 错误的 `code` 和运行失败的 `error.code` 共用这一组值。按 `code` 判断类别，`detail` 和 `message` 只用于阅读。")
	b.WriteString("错误响应里的 `next_actions` 比这里的通用建议更具体，有时优先按它处理。\n\n")
	b.WriteString("| code | 含义 | 下一步 |\n| --- | --- | --- |\n")
	for _, v := range one.Content {
		code := scalar(get(v, "const"))
		if code == "" {
			return nil, errors.New("ErrorCode value without const")
		}
		meaning, next, _ := strings.Cut(scalar(get(v, "description")), "下一步：")
		fmt.Fprintf(&b, "| `%s` | %s | %s |\n", code, cell(meaning), cell(next))
	}
	return []byte(b.String()), nil
}
